exercises.solution:
export const REFUSAL_MESSAGE = "I don't have a confident answer from our help center for that — let me bring in a teammate who can help.";

export function isRefusal(answer) {
  return answer.trim() === REFUSAL_MESSAGE || /\bi don'?t know\b/i.test(answer.trim());
}

export function extractCitations(answer) {
  const out = new Set();
  for (const m of answer.matchAll(/\[(\d+)\]/g)) out.add(Number(m[1]));
  return [...out].sort((a, b) => a - b);
}

export function verifyCitations(answer, chunkCount) {
  const cited = extractCitations(answer);
  const invalid = cited.filter((n) => n < 1 || n > chunkCount);
  return { cited, invalid, grounded: cited.length > 0 && invalid.length === 0 };
}

export function ungrounded(answer, chunkCount) {
  if (isRefusal(answer)) return false;
  return !verifyCitations(answer, chunkCount).grounded;
}

tests.code:
assert.equal(typeof mod.extractCitations, 'function', 'export a function named extractCitations');
assert.deepEqual(mod.extractCitations('See [2], then [1], and again [2].'), [1, 2]);
assert.deepEqual(mod.extractCitations('No markers here.'), []);

assert.equal(typeof mod.verifyCitations, 'function', 'export a function named verifyCitations');
assert.deepEqual(mod.verifyCitations('Works exactly once [3].', 2), { cited: [3], invalid: [3], grounded: false });
assert.deepEqual(mod.verifyCitations('Works exactly once [2].', 2), { cited: [2], invalid: [], grounded: true });

assert.equal(typeof mod.ungrounded, 'function', 'export a function named ungrounded');
assert.equal(mod.ungrounded("I don't know.", 0), false);
assert.equal(mod.ungrounded(mod.REFUSAL_MESSAGE, 3), false);

